describe('ZimmSizeChipGroup — roving tabindex resync on rerender', () => {
  test('moves the tab stop to match a new selectedValue passed in after mount', () => {
    const { rerender } = wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" />);
    const initialStops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(initialStops[0]).toHaveAttribute('data-size-value', 'xs');

    rerender(
      <IntlProvider locale="en" defaultLocale="en">
        <ZimmSizeChipGroup values={FOUR} selectedValue="l" />
      </IntlProvider>,
    );

    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveAttribute('data-size-value', 'l');
  });

  test('moves the tab stop off the previously-selected size once it becomes disabled', () => {
    const values = [val('xs', 'XS'), val('s', 'S'), val('m', 'M')];
    const { rerender } = wrap(<ZimmSizeChipGroup values={values} selectedValue="s" />);
    const initialStops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(initialStops[0]).toHaveAttribute('data-size-value', 's');

    const valuesWithSDisabled = [val('xs', 'XS'), val('s', 'S', { isDisabled: true }), val('m', 'M')];
    rerender(
      <IntlProvider locale="en" defaultLocale="en">
        <ZimmSizeChipGroup values={valuesWithSDisabled} selectedValue="s" />
      </IntlProvider>,
    );

    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).not.toHaveAttribute('data-size-value', 's');
    expect(stops[0]).toHaveAttribute('data-size-value', 'xs');
  });
});

